-- T1: Transfer $100 from A to B
BEGIN;
UPDATE accounts SET balance = balance - 100 WHERE id = 'A';  -- balance A: 900
-- (T1 has not committed yet)

-- T2: Read at READ UNCOMMITTED
BEGIN;
SET TRANSACTION ISOLATION LEVEL READ UNCOMMITTED;
SELECT balance FROM accounts WHERE id = 'A';  -- returns 900 (dirty!)
SELECT balance FROM accounts WHERE id = 'B';  -- returns 1000 (credit not yet applied)
-- T2 calculates total = 1900, but the "real" total is 2000
COMMIT;

-- T1 rolls back — account A is restored to 1000
ROLLBACK;
-- T2 acted on a value that never truly existed

-- Invariant: at least one doctor must be on call at all times
-- Currently: Alice (on_call=true), Bob (on_call=true)

-- T1: Alice goes off call
BEGIN;
SELECT COUNT(*) FROM doctors WHERE on_call = true;  -- returns 2 (Alice sees Alice+Bob)
UPDATE doctors SET on_call = false WHERE name = 'Alice';
COMMIT;

-- T2: Bob goes off call (concurrent with T1, same snapshot)
BEGIN;
SELECT COUNT(*) FROM doctors WHERE on_call = true;  -- returns 2 (Bob sees Alice+Bob)
UPDATE doctors SET on_call = false WHERE name = 'Bob';
COMMIT;

-- RESULT: Both committed. Zero doctors on call. Invariant violated.
-- Under SI both transactions read a consistent snapshot (count=2),
-- passed the check, and updated *different* rows — no write-write conflict.
